INSERT INTO questions (id, content, difficulty, sub_category_id) VALUES
('b0000000-0000-0000-0015-000000000000', 'AWS(Amazon Web Services)란 무엇이며, 왜 그렇게 널리 사용되나요?', 'EASY', 'b0000000-0000-0000-0000-000000000015'),
('b0000000-0000-0000-0015-000000000001', 'AWS에서 EC2와 S3는 각각 어떤 서비스인가요?', 'EASY', 'b0000000-0000-0000-0000-000000000015'),
('b0000000-0000-0000-0015-000000000002', 'AWS의 가용 영역(Availability Zone)과 리전(Region)의 차이는 무엇인가요?', 'EASY', 'b0000000-0000-0000-0000-000000000015'),
('b0000000-0000-0000-0015-000000000003', '확장성(Scalability)과 고가용성(High Availability)을 AWS에서 구현하려면 어떤 서비스를 활용할 수 있나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000015'),
('b0000000-0000-0000-0015-000000000004', 'RDS와 DynamoDB의 차이는 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000015'),
('b0000000-0000-0000-0015-000000000005', 'CloudFront는 어떤 서비스이며 어떻게 동작하나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000015'),
('b0000000-0000-0000-0015-000000000006', 'AWS Lambda란 무엇이며, 어떤 때 사용하면 좋은가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000015'),
('b0000000-0000-0000-0015-000000000007', 'S3의 버킷(Bucket) 정책은 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000015'),
('b0000000-0000-0000-0015-000000000008', 'AWS CloudWatch는 무엇을 모니터링하는 서비스인가요?', 'EASY', 'b0000000-0000-0000-0000-000000000015'),
('b0000000-0000-0000-0015-000000000009', 'AWS VPC란 무엇이고, 서브넷(Subnet)은 왜 필요하나요?', 'EASY', 'b0000000-0000-0000-0000-000000000015'),
('b0000000-0000-0000-0015-00000000000A', 'AWS IAM(Identity and Access Management)의 역할은 무엇인가요?', 'EASY', 'b0000000-0000-0000-0000-000000000015'),
('b0000000-0000-0000-0015-00000000000B', '로드 밸런서(Elastic Load Balancing)와 오토 스케일링(Auto Scaling)은 어떻게 협력하나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000015'),
('b0000000-0000-0000-0015-00000000000C', 'AWS에서 데이터베이스를 수직/수평으로 확장하는 방법은?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000015'),
('b0000000-0000-0000-0015-00000000000D', 'AWS CloudFormation과 Terraform의 차이는 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000015'),
('b0000000-0000-0000-0015-00000000000E', 'AWS에서 비용 최적화를 위해 할 수 있는 방법은 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000015'),
('b0000000-0000-0000-0015-00000000000F', 'AWS Well-Architected 프레임워크의 핵심 요소는 무엇인가요?', 'HARD', 'b0000000-0000-0000-0000-000000000015'),
('b0000000-0000-0000-0015-000000000010', 'AWS 서비스 간 통합(예: S3 이벤트로 Lambda 트리거)은 어떻게 이루어지나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000015'),
('b0000000-0000-0000-0015-000000000011', '다중 계정(Multiple AWS Accounts)을 운영할 때 고려해야 할 사항은?', 'HARD', 'b0000000-0000-0000-0000-000000000015'),
('b0000000-0000-0000-0015-000000000012', 'AWS에서 클라우드 보안을 강화하기 위해 취할 수 있는 조치는?', 'HARD', 'b0000000-0000-0000-0000-000000000015'),
('b0000000-0000-0000-0015-000000000013', '멀티 리전(Multi-Region) 배포의 이점과 고려사항은 무엇인가요?', 'HARD', 'b0000000-0000-0000-0000-000000000015'),
('b0000000-0000-0000-0015-000000000014', '클라우드 보안에서 AWS가 책임지는 부분과 사용자가 책임지는 부분은? (Shared Responsibility Model)', 'MEDIUM', 'b0000000-0000-0000-0000-000000000015'),
('b0000000-0000-0000-0015-000000000015', '웹 애플리케이션을 AWS에 확장성 있고 내결함성 있게 설계하려면 어떻게 하시겠습니까?', 'HARD', 'b0000000-0000-0000-0000-000000000015'),
('b0000000-0000-0000-0015-000000000016', '특정 시나리오: 사용자가 갑자기 급증하는 상황에서 AWS에서 어떻게 대응하겠습니까?', 'HARD', 'b0000000-0000-0000-0000-000000000015'),
('b0000000-0000-0000-0015-000000000017', '관계형 데이터베이스(RDS) 대신 NoSQL(DynamoDB)을 선택해야 하는 시나리오는?', 'HARD', 'b0000000-0000-0000-0000-000000000015'),
('b0000000-0000-0000-0015-000000000018', 'AWS Lambda 함수를 활용해야 하는 애플리케이션 시나리오는?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000015');
